            level1 = json.loads(content_str)
        except:
            return None
        if 'result' not in level1:
            return None
        try:
            level2 = json.loads(level1['result'])
        except:
            return None
        if not level2.get('success', False):
            return None
        stdout = level2.get('data', {}).get('stdout', '')
        return stdout
    except:
        return None

# Decode lines 13, 17, 22 which look promising
